n("סופיא", "סופיא היא המילה היוונית לחוכמה, והיא מוכרת גם מהמילה פילוסופיה, אהבת החוכמה. סופיה היא כתיב אחר של אותו שם, וסופי היא צורה קצרה שלו בשפות של אירופה. השם עבר מהיוונית לשפות רבות, וכל שפה כתבה אותו קצת אחרת.", ["סופיה", "סופי"])
n("עמיאל", "עמיאל מחבר את המילים עמי ואל, ופירושו אלוהים הוא העם שלי. בעברית העתיקה המילה עם תיארה גם בן משפחה קרוב, ולכן יש שמפרשים את השם גם כאלוהים הוא קרובי. בתורה עמיאל הוא אחד המרגלים ששלח משה, נציג שבט דן.")
n("פאיז", "פאיז היא מילה ערבית למי שזוכה ומצליח, ובעיקר למי שמנצח בתחרות או במאבק. היא באה מהשורש הערבי פ־ו־ז, שעניינו הצלחה וזכייה. מאותו שורש נבנו גם פואז ופאוזי, ופאיזה היא הצורה לבנות.", ["פאיזה"])
n("פז", "פז היא מילה עברית עתיקה לזהב טהור ומזוקק, בלי תערובת של מתכות אחרות. בעברית של היום היא מוכרת מצירופים כמו הזדמנות פז ויקר מפז, שמתארים דבר יקר מאוד שלא כדאי להחמיץ.")
n("תייסיר", "תייסיר היא מילה ערבית להקלה, לעשייה שהופכת דבר קשה לפשוט ונוח יותר. היא באה מהשורש הערבי י־ס־ר, שעניינו קלות ונוחות. מאותו שורש נבנו גם יאסר ויוסרא.")
n("איילול", "איילול הוא שמו של חודש ספטמבר בערבית של ארצות הלבנט, והוא קרוב לשם החודש העברי אלול. שמות החודשים האלה באים מלוח השנה הבבלי העתיק, ומשם עברו גם לעברית וגם לערבית. אילול הוא כתיב אחר של אותו שם.", ["אילול"])
n("אלאן", "אלאן הוא שם אירופי עתיק, שהגיע לאנגליה ולצרפת בימי הביניים מחבל בריטני שבצפון־מערב צרפת. מקור השם אינו ודאי: יש שקושרים אותו למילה קלטית לסלע, ויש שקושרים אותו לאלאנים, עם נוודים קדום.")
n("אלירז", "אלירז מחבר את המילים אלי ורז, ופירושו לאלוהיי יש סוד. רז היא מילה עתיקה לסוד, שהגיעה לעברית דרך הארמית. בעברית של היום היא מוכרת מצירופים כמו רזי הטבע, וגם מהשם רז, שנבנה עליה.", ["רז"])
n("אסלאן", "אסלאן היא המילה הטורקית לאריה, והיא קיימת גם בשפות טורקיות אחרות, כמו האזרית והטטרית. המילה עברה גם לפרסית ולשפות של הבלקן, וארסלאן היא צורה עתיקה יותר שלה.")
n("אשל", "אשל הוא עץ שגדל במדבר ובאדמה מלוחה, ועליו קטנים ודקים כמו קשקשים. בתורה אברהם נוטע אשל בבאר שבע, ועד היום נוטעים אשלים בנגב כי הם עמידים לחום וליובש. במדרש נדרשה המילה אשל כראשי תיבות של אכילה, שתייה ולינה, סמל להכנסת אורחים.")
n("גנאת", "גנאת היא צורת הרבים של המילה הערבית לגן. בערבית, כמו בעברית, גן הוא מקום ירוק עם עצים, פרחים ומים. השם קרוב למילה העברית גנים, ובשתי השפות הוא בא מאותו שורש, ג־נ־ן.")
n("זיסל", "זיסל הוא שם יידי, והוא בא מהמילה ביידיש זיס, מתוק, הקרובה למילה הגרמנית בעלת אותו פירוש. בסופו הסיומת ־ל, שביידיש מוסיפה לשם נימה של חיבה. באותה דרך נבנה גם השם היידי זיסקינד, ילד מתוק.")
n("יוני", "יוני בנוי על המילה יונה, והסיומת ־י מוסיפה לו את המשמעות היונה שלי. היונה מזוהה עם שלום ועם רוך, והיא כינוי חיבה ותיק בעברית. יוני הוא גם צורת חיבה של יונתן, שפירושו ה׳ נתן.", ["יונתן", "יונה"])
n("ליבה", "ליבה הוא שם יידי, והוא בא מהמילה ביידיש ליב, אהוב, הקרובה למילה הגרמנית ליבה, אהבה. ליבא הוא כתיב אחר של אותו שם. בעברית נשמע בו גם הצליל של המילה לב, ובעברית של היום ליבה היא גם החלק הפנימי והמרכזי של דבר.", ["ליבא"])
n("לידור", "לידור מחבר את המילים לי ודור, ופירושו דור שלי. דור הם כל האנשים שחיים באותה תקופה, וגם השרשרת של הורים, ילדים ונכדים. באותה דרך נבנו שמות עבריים נוספים שמתחילים במילה לי, כמו ליאור ולירון.")
n("מוהנד", "מוהנד היא מילה ערבית לחרב שעשויה מפלדה הודית. המילה באה מהשם הערבי של הודו, הינד, כי בימי קדם הגיעה מהודו פלדה משובחת לחרבות. בשירה הערבית העתיקה החרב ההודית היא דימוי לחדות ולחוזק.")
n("מלאני", "מלאני באה מהמילה היוונית מלאס, שחור וכהה, והיא קרובה למילה מלנין, שם החומר שנותן צבע לעור ולשיער. מאותה מילה יוונית באה גם המילה מלנכוליה. בכל שפה של אירופה השם נכתב ונהגה קצת אחרת.")
n("מתאו", "מתאו הוא הצורה האיטלקית של השם העברי מתתיהו, שמחבר את המילים מתת ויהו. מתת היא מילה עתיקה למתנה, מהשורש נ־ת־ן, כמו המילים מתן ומתנה. בשפות אחרות של אירופה השם קיבל צורה משלו, כמו מתיאס ומתיו.", ["מתתיהו"])
n("נוריאל", "נוריאל מחבר את המילים נורי ואל, ופירושו אלוהים הוא האור שלי. נור היא מילה ארמית לאש ולאור, והיא קרובה למילים העבריות נר ומנורה. הצורה הקצרה נורי בנויה על אותה מילה.", ["נורי"])
n("נירי", "נירי בנוי על המילה ניר, שדה שנחרש והוכן לזריעה, והסיומת ־י מוסיפה לו את המשמעות השדה שלי. ניר הוא גם חלק משמם של יישובים בארץ, כמו ניר עם וניר דוד.", ["ניר"])
n("נעומי", "נעומי הוא הכתיב של השם נעמי בשפות של אירופה, כמו באנגלית ובצרפתית. השם העברי בא מהשורש נ־ע־ם, שממנו באות המילים נעים ונעימות, ופירושו הנעימה שלי. מאותו שורש נבנו גם נעמה ונועם.", ["נעמי"])
n("פיראס", "פיראס הוא שם ערבי, ופירושו תבונה וחדות, היכולת להבין דבר מתוך סימנים קטנים. הוא בא מהשורש הערבי פ־ר־ס, שממנו באה גם המילה פארס, פרש ורוכב על סוס, והשורש קרוב לשורש של המילה העברית פרש.")
n("צוף", "צוף הוא הנוזל המתוק שפרחים מפרישים, ודבורים אוספות אותו ומכינות ממנו דבש. בדרך מפרח לפרח הן מעבירות אבקה ועוזרות לצמחים להתרבות. בתנ״ך נופת צופים היא דבש שנוטף מחלות הדבש, דימוי לדבר מתוק מאוד.")
n("רימון", "רימון הוא פרי עם קליפה קשה וגרעינים רבים, אדומים ועסיסיים, ועץ הרימון גדל בארץ מימי קדם. בתורה הרימון הוא אחד משבעת המינים שבהם התברכה הארץ. רימונים היו גם קישוט בבגדי הכהן הגדול, ועד היום מכנים כך את הקישוטים שעל ספר התורה.")
n("רמזי", "רמזי היא מילה ערבית לסמלי, למה שמתבטא ברמז ולא במפורש. היא באה מהשורש הערבי ר־מ־ז, אותו שורש של המילה העברית רמז, ובשתי השפות הוא מתאר סימן שמבינים ממנו יותר ממה שנאמר.")
n("אורית", "אורית בנויה על המילה אור, עם הסיומת ־ית, שבעברית נותנת לשמות צורה של לשון נקבה, כמו בשמות עדית ושירית. בארמית המילה הקרובה אורייתא היא כינוי לתורה. מאותה מילה נבנו גם אורה, אורי ואוריה.", ["אור", "אורה"])
n("אורלי", "אורלי מחבר את המילים אור ולי, ופירושו יש לי אור. באותה דרך נבנו שמות נוספים שמסתיימים במילה לי, כמו שירלי ושי־לי. אורלי היא גם שמה של עיירה בצרפת, ליד פריז, אבל השם העברי בנוי על המילים העבריות ואינו קשור אליה.")
n("אילור", "אילור מחבר את המילים אי ואור, ופירושו אי של אור. אי הוא פיסת יבשה שמוקפת מים מכל הצדדים, והצירוף מעלה תמונה של מקום מואר באמצע הים. מהמילה אור נבנו באותה דרך גם ליאור ואליאור.")
n("אלעד", "אלעד מחבר את המילים אל ועד, ופירושו אלוהים לעד, לתמיד. עד היא מילה עתיקה לנצח ולזמן שאין לו סוף, כמו בצירוף לעולם ועד. אליעד הוא שם קרוב, שבנוי על אותן מילים, ואלעד הוא גם שמה של עיר בארץ, ליד ראש העין.", ["אליעד"])
n("ג'אבר", "ג'אבר היא מילה ערבית למי שמחזק ומתקן, ובעיקר למי שמחבר מחדש דבר שנשבר. היא באה מהשורש הערבי ג׳־ב־ר, שממנו באה גם המילה אלגברה, שפירושה בערבית איחוי של חלקים שבורים. השורש קרוב לשורש העברי ג־ב־ר, של המילים גבר וגבורה.")
n("דליה", "דליה היא פרח גינה צבעוני, שמקורו במקסיקו ובמרכז אמריקה. בעברית דליה היא גם ענף של גפן, ומאותו שורש, ד־ל־ה, באה גם המילה דלי. דליה היא גם שמו של קיבוץ ברמת מנשה.")
n("חדוה", "חדוה היא מילה עתיקה לשמחה, מהשורש ח־ד־ה, שממנו בא גם הפועל לחדות, לשמוח. בתנ״ך היא מופיעה בספרים המאוחרים, ובארמית חדווא היא המילה הרגילה לשמחה. בעברית של היום היא מוכרת בעיקר מהשירה ומהשפה החגיגית.")
n("יגאל", "יגאל בא מהשורש ג־א־ל, ופירושו הוא יגאל, יציל וישחרר. מאותו שורש באות גם המילים גאולה וגואל. בתורה יגאל הוא אחד המרגלים ששלח משה, נציג שבט יששכר.")
n("להב", "להב היא מילה עתיקה לשלהבת, לקצה הבוער והמתנופף של האש. מכאן נקרא להב גם החלק החד והמבריק של הסכין או החרב, שנוצץ כמו אש. מאותה מילה באות גם המילים להבה ושלהבת, והפועל להתלהב.")
n("לוג'יין", "לוג'יין היא מילה ערבית לכסף, המתכת הבהירה והמבריקה שממנה עושים תכשיטים וכלים. בעברית כותבים את השם בכמה דרכים, כמו לוג'ין ולוגין, וכולן אותו שם ערבי.", ["לוג'ין", "לוגין"])
n("משולם", "משולם בא מהשורש ש־ל־ם, שממנו באות גם המילים שלם, שלום ותשלום, ופירושו שלם ומושלם. בתנ״ך זה שמם של כמה אנשים בספרים המאוחרים, ובהם אחד מאלה שתיקנו את חומות ירושלים בימי נחמיה.")
n("נדים", "נדים היא מילה ערבית לחבר קרוב, מי שיושבים איתו לשיחה ארוכה, בעיקר בשעות הערב. בעבר המילה תיארה גם את מי שישב בחצר של שליט ושוחח איתו. היא באה מהשורש הערבי נ־ד־ם.")
n("סאמיה", "סאמיה היא הצורה לבנות של סאמי, מהמילה הערבית לנעלה ולרם. היא באה מהשורש הערבי ס־מ־ו, שעניינו גובה ורוממות, ומאותו שורש באה גם המילה הערבית לשמיים. השורש קרוב לשורש העברי של המילה שמיים.", ["סאמי"])
n("סופיאן", None, note="Old Arabic name; the card only says so, and its meaning is not well established, so no story.")
n("סקר", "סקר היא המילה הערבית לבז, עוף דורס קטן ומהיר, שצד ציפורים בתעופה. בארצות המדבר נהגו מימי קדם לאלף בזים לציד, וסקר הוא שמם בערבית של הבזים האלה.")
n("עזאם", "עזאם בא מהשורש הערבי ע־ז־ם, שעניינו החלטה ונחישות, והוא מתאר מי שהחליט על דבר ודבק בו. מאותו שורש באה המילה הערבית עזם, נחישות וכוח רצון, וגם השם עזמי.")
n("עשהאל", "עשהאל מחבר את המילים עשה ואל, ופירושו מה שאלוהים עשה, או שאלוהים יצר. בתנ״ך עשהאל הוא אחיו של יואב, שר הצבא של דוד המלך, והוא מתואר כרץ מהיר מאוד.")
n("ריילי", "ריילי הוא שם אירי ואנגלי. מקובל לקשר אותו לשם משפחה אירי עתיק, אוריילי, ויש שקושרים אותו לשם מקום באנגליה, שפירושו קרחת יער שבה גדל שיפון. השם עבר משמות משפחה לשמות פרטיים.")
n("שריף", "שריף היא מילה ערבית למכובד ולאציל, למי שזוכה לכבוד בזכות מעשים טובים. היא באה מהשורש הערבי ש־ר־ף, שעניינו מקום גבוה וכבוד, ומאותו שורש באה גם המילה הערבית שרף, כבוד.")
n("תומי", "תומי בנוי על המילה תום, יושר ופשטות של לב, והסיומת ־י מוסיפה לו את המשמעות התום שלי. הוא גם צורת חיבה של תומאס, שם שבא מהמילה הארמית תאומא, תאום. טומי הוא כתיב אחר של צורת החיבה הזאת.", ["תום", "תומאס", "טומי"])
n("אביבה", "אביבה בנויה על המילה אביב, עונת השנה שבה הטבע פורח והתבואה מבשילה. במקור אביב הוא שיבולת צעירה ורכה, ועל שמה נקראה העונה. אביבה היא צורת לשון נקבה של השם אביב.", ["אביב"])
n("אלטע", "אלטע בא מהמילה ביידיש אַלטע, זקנה, הקרובה למילה הגרמנית אלט, ישן וזקן. זו הצורה לבנות של השם אלטר, ושניהם מבטאים משאלה לחיים ארוכים. באותה רוח ניתן גם השם העברי חיה, שגם הוא בנוי על איחול לחיים.", ["אלטר", "אלתר"])
n("אלטר", "אלטר בא מהמילה ביידיש אַלטער, זקן, הקרובה למילה הגרמנית אלט. השם מבטא משאלה לחיים ארוכים ולגיל מבוגר. אלתר הוא כתיב אחר של אותו שם, ואלטע היא הצורה לבנות.", ["אלתר", "אלטע"])
